function coreCategoryGrid() {
  const coreCards = [
    ['surface','Fläche','Desinfektion & Reinigung'],
    ['hands','Hände & Haut','Händedesinfektion & Pflege'],
    ['instruments','Instrumente','Aufbereitung & Desinfektion'],
    ['application','Applikation','Spendersysteme & Zubehör']
  ];
  return `<div class="category-grid">${coreCards.map(([key,title,sub]) => `<button class="category-card ${key}" data-category="${key}"><span class="category-icon">${icon(key)}</span><span><strong>${title}</strong><small>${sub}</small></span><b>›</b></button>`).join('')}</div>`;
}
function menuScreen() {
  let cards = [
    ['surface','Fläche','Desinfektion & Reinigung'],
    ['hands','Hände & Haut','Händedesinfektion & Pflege'],
    ['instruments','Instrumente','Aufbereitung & Desinfektion'],
    ['application','Applikation','Spendersysteme & Zubehör'],
    ['advisor','Produktberater','In wenigen Fragen zum passenden Produkt'],
    ['compare','Produktvergleich','Bis zu drei Produkte direkt vergleichen'],
    ['competition','Wettbewerbsvergleich','Kundenpreis eingeben, Ersparnis berechnen'],
    ['offer','Kundenübersicht','Markierte Produkte als Angebot oder PDF'],
    ['summary','Kundenzusammenfassung','Mit ★ markierte Produkte per E-Mail an den Kunden'],
    ['report','Besuchsbericht','CRM-Zusammenfassung und Follow-up'],
    ['dashboard','Follow-up Dashboard','Offene Termine und Aufgaben im Blick'],
    ['messe','Messe','Kontakt live erfassen und an den Innendienst senden'],
    ['pm','Produktmanagement','Zuständigkeiten und Kontakte der Produktmanager'],
    ['downloads','Downloads','Aktuelle Unterlagen online'],
    ['all','Alle Funktionen','Gesamte Produktübersicht öffnen']
  ];
  if (!can('reports')) cards = cards.filter(card => !['report','dashboard'].includes(card[0]));
  if (!can('sales')) cards = cards.filter(card => !['compare','offer','summary'].includes(card[0]));
  const coreKeys = ['surface','hands','instruments','application'];
  const toolCards = cards.filter(c => !coreKeys.includes(c[0]));
  const today = new Date().toISOString().slice(0,10);
  const openReports = state.savedReports.filter(r => (r.taskStatus || 'Offen') !== 'Erledigt');
  const due = openReports.filter(r => r.followUp && r.followUp <= today).length;
  const favoriteProducts = [...new Set(state.favorites.map(f => f.id))].map(id => PRODUCTS.find(p => p.id === id)).filter(Boolean).slice(0,4);
  const recentProducts = state.recent.map(id => PRODUCTS.find(p => p.id === id)).filter(Boolean).slice(0,4);
  const searchResults = state.globalQuery.trim() ? PRODUCTS.filter(p => `${p.name} ${p.kind} ${p.sku} ${p.summary}`.toLowerCase().includes(state.globalQuery.toLowerCase())).slice(0,8) : [];
  return `<main class="page menu-page cockpit-page">
    <section class="cockpit-hero compact"><div><span class="eyebrow">Dr. Schumacher Sales Companion</span><h1>Aktiv: ${state.customerMode?'Preise ausgeblendet':state.priceList}</h1></div></section>
    ${coreCategoryGrid()}
    <label class="global-search">${icon('search')}<input id="globalSearch" value="${escapeHtml(state.globalQuery)}" placeholder="Produkt, Artikelnummer oder Anwendung suchen"><span>⌘ K</span></label>
    ${state.globalQuery.trim() ? `<section class="cockpit-search-results"><div class="section-heading"><div><span class="eyebrow">Sofortsuche</span><h2>${searchResults.length} Treffer</h2></div><button class="secondary-button" data-action="clear-global-search">Suche löschen</button></div><div class="product-list">${searchResults.map(productCard).join('') || '<div class="empty-state"><h2>Kein Produkt gefunden</h2><p>Versuchen Sie einen anderen Suchbegriff.</p></div>'}</div></section>` : ''}
    <section class="cockpit-columns">
      <div class="cockpit-panel"><div class="panel-title"><div><span class="eyebrow">Schnellzugriff</span><h2>Zuletzt angesehen</h2></div><button data-category="recent">Alle</button></div><div class="mini-products">${recentProducts.map(miniProductCard).join('') || '<p class="muted-copy">Noch keine Produkte geöffnet.</p>'}</div></div>
      <div class="cockpit-panel"><div class="panel-title"><div><span class="eyebrow">Persönlich</span><h2>Favoriten</h2></div><button data-nav="favorites">Alle</button></div><div class="mini-products">${favoriteProducts.map(miniProductCard).join('') || '<p class="muted-copy">Noch keine Favoriten gespeichert.</p>'}</div></div>
    </section>
    <section class="cockpit-stats">
      <button data-category="dashboard"><strong>${due}</strong><span>heute / überfällig</span><small>Follow-ups öffnen →</small></button>
      <button data-category="favorites"><strong>${state.favorites.length}</strong><span>Favoriten</span><small>Schnellzugriff →</small></button>
      <button data-category="recent"><strong>${state.recent.length}</strong><span>Zuletzt angesehen</span><small>Verlauf öffnen →</small></button>
      <button data-category="settings"><strong>${Object.keys(state.prices).length}</strong><span>Preisdatensätze</span><small>Import verwalten →</small></button>
    </section>
    <div class="section-heading"><div><span class="eyebrow">Weitere Funktionen</span><h2>Werkzeuge</h2></div></div>
    <div class="category-grid compact-grid">${toolCards.map(([key,title,sub]) => `<button class="category-card ${key}" data-category="${key}"><span class="category-icon">${icon(key)}</span><span><strong>${title}</strong><small>${sub}</small></span><b>›</b></button>`).join('')}</div>
    <section class="online-card"><div class="online-dot"></div><div><strong>Unterlagen immer aktuell</strong><p>Produktinformationen, Datenblätter und Bilder werden direkt von schumacher-online.com geöffnet.</p></div><a href="${OFFICIAL.home}" target="_blank" rel="noopener">Website öffnen</a></section>
  </main>`;
}

function miniProductCard(product) {
  return `<button class="recent-card" data-product="${product.id}"><span class="recent-card-icon" style="--product-color:${product.color}">${product.category==='hands'?'✋':product.category==='surface'?'▦':product.category==='instruments'?'✂':'▣'}</span><span class="recent-card-copy"><strong>${product.name}</strong><small>${product.kind}</small></span><b>›</b></button>`;
}

function productsScreen() {
  if (state.category === 'downloads') return downloadsScreen();
  const names = {surface:'Fläche',hands:'Hände & Haut',instruments:'Instrumente',application:'Applikation',all:'Alle Produkte'};
  const spectra = ['all','begrenzt viruzid','begrenzt viruzid PLUS','viruzid','sporizid'];
  const list = PRODUCTS.filter(p =>
    (state.category === 'all' || p.category === state.category) &&
    (!state.query || `${p.name} ${p.kind} ${p.sku}`.toLowerCase().includes(state.query.toLowerCase())) &&
    (state.spectrum === 'all' || p.spectrum.includes(state.spectrum))
  );
  return `<main class="page products-page">
    <div class="section-heading"><div><span class="eyebrow">Produktbereich</span><h1>${names[state.category]}</h1></div><span class="result-count">${list.length} Produkte</span></div>
    <label class="search-box">${icon('search')}<input id="search" value="${escapeHtml(state.query)}" placeholder="Produktname oder Artikelnummer suchen"></label>
    <div class="filter-row">${spectra.map(s => `<button class="filter-chip ${s==='all'?'':spectrumClass(s)} ${state.spectrum===s?'active':''}" data-spectrum="${s}">${s==='all'?'Alle':s}</button>`).join('')}</div>
    <div class="product-list">${list.map(productCard).join('') || '<div class="empty-state"><h2>Keine Produkte gefunden</h2><p>Bitte ändern Sie Ihre Suche oder den Filter.</p></div>'}</div>
  </main>`;
}

function productCard(product, variantSize) {
  // Note: never pass this directly to Array.prototype.map for a variant-aware call —
  // map also passes the index as a 2nd argument, so we only honor a real size string.
  const hasVariant = typeof variantSize === 'string';
  const refSize = (hasVariant && product.sizes.includes(variantSize)) ? variantSize : product.sizes[0];
  const price = resolvePrice(product, refSize);
  const perUnit = perUnitLabel(product, refSize);
  const favorite = hasVariant ? state.favorites.some(f => f.id === product.id && f.size === refSize) : state.favorites.some(f => f.id === product.id);
  return `<article class="product-row" data-product="${product.id}">
    <div class="product-image" style="--product-color:${product.color}">${product.photo?`<img src="${product.photo}" alt="${escapeHtml(product.name)}">`:`<span>${product.category==='hands'?'✋':product.category==='surface'?'▦':product.category==='instruments'?'✂':'▣'}</span>`}</div>
    <div class="product-copy"><small>${product.kind}</small><h2>${product.name}</h2><div class="badges">${product.spectrum.map(spectrumBadge).join('')}</div><p>Art.-Nr. ${resolveArtNr(product, refSize)} · ${refSize}</p></div>
    <div class="row-price">${(state.customerMode||inMesseContext())?'<strong class="hidden-price">Preis verborgen</strong>':`<strong>${money(price)}</strong><small>${perUnit || state.priceList}</small>`}</div>
    <button class="favorite-button ${favorite?'active':''}" data-favorite="${product.id}" ${hasVariant?`data-favorite-size="${escapeHtml(refSize)}"`:''} aria-label="Favorit">${icon('star')}</button>
    <span class="chevron">›</span>
  </article>`;
}

function detailScreen() {
  const p = PRODUCTS.find(x => x.id === state.selected);
  if (!p) { state.screen = 'products'; return productsScreen(); }
  if (!state.size) state.size = p.sizes[0];
  const price = resolvePrice(p, state.size);
  const favorite = state.favorites.some(f => f.id === p.id && f.size === state.size);
  const markedSizes = state.favorites.filter(f => f.id === p.id).map(f => f.size);
  return `<main class="page detail-page">
    <section class="detail-hero">
      <div class="detail-image" style="--product-color:${p.color}">${(() => { const img = (p.sizePhotos && p.sizePhotos[state.size]) || p.photo; return img ? `<img src="${img}" alt="${escapeHtml(p.name)}">` : `<div class="bottle"><span>${p.name.split(' ')[0]}</span></div>`; })()}</div>
      <div class="detail-copy"><span class="eyebrow">${p.kind}</span><div class="title-line"><h1>${p.name}</h1><button class="favorite-button large ${favorite?'active':''}" data-favorite="${p.id}" data-favorite-size="${escapeHtml(state.size)}" aria-label="Favorit (${escapeHtml(state.size)})">${icon('star')}</button></div><div class="badges">${p.spectrum.map(spectrumBadge).join('')}</div><p>${p.summary}</p><small class="meta-line">Artikelnummer: ${resolveArtNr(p, state.size)}</small>${resolveVE(p, state.size) ? `<small class="meta-line">VE: ${resolveVE(p, state.size)} Stück</small>` : ''}${markedSizes.length ? `<small class="marked-sizes">★ markiert: ${markedSizes.map(escapeHtml).join(', ')}</small>` : ''}</div>
    </section>
    <section class="detail-grid">
      <div class="info-card"><h2>Das Wichtigste auf einen Blick</h2>${p.einwirkzeitEntries && p.einwirkzeitEntries.length ? `<div class="einwirkzeit-list">${p.einwirkzeitEntries.map(e => `<div class="einwirkzeit-badge ${e.kind}">⏱ ${escapeHtml(e.label)} in ${escapeHtml(e.time)}${e.detail ? ` <span class="einwirkzeit-tier">${escapeHtml(e.detail)}</span>` : ''}</div>`).join('')}</div>` : ''}<ul>${p.facts.map(f => `<li><span>✓</span>${f}</li>`).join('')}</ul>${p.ingredients ? `<div class="ingredients-block"><strong>Inhaltsstoffe</strong><span>${escapeHtml(p.ingredients)}</span></div>` : ''}<div class="info-warning">Verbindliche Anwendung, Einwirkzeiten und Sicherheit bitte immer anhand der aktuellen offiziellen Produktinformation prüfen.</div></div>
      <div class="price-card-detail"><span>Gebinde auswählen${p.sizes.length>1?' · anklicken markiert die Variante als Favorit':''}</span><div class="size-selector">${p.sizes.map(size => {
        const isMulti = p.sizes.length > 1;
        const active = isMulti ? state.favorites.some(f=>f.id===p.id && f.size===size) : (state.size===size);
        return `<button class="${active?'active':''}" data-size="${size}" ${isMulti?`data-size-favorite="${p.id}"`:''}>${escapeHtml(size)}</button>`;
      }).join('')}</div>${p.sizeNotes && p.sizeNotes[state.size] ? `<small class="size-note">${p.sizeNotes[state.size]}</small>` : ''}<div class="price-display"><div>${(state.customerMode||inMesseContext())?'<strong class="hidden-price">Preis verborgen</strong>':`<small>Ihr Preis</small><strong>${money(price)}</strong><span>${perUnitCalc(p,state.size) || 'zzgl. MwSt.'}</span>`}</div>${(state.customerMode||inMesseContext())?'':`<select class="price-list-inline" data-action="price-list-inline" aria-label="Preisliste wechseln">${['UVP','PL 1','PL 2','PL 3','PL 4','PL 5'].map(o=>`<option value="${o}" ${state.priceList===o?'selected':''}>${o}</option>`).join('')}</select>`}</div>
        ${(state.customerMode||inMesseContext()) ? '' : `<button class="primary-button compact vs-button" data-action="compare-competitor" data-product="${p.id}">${icon('competition')}<span>Mit Wettbewerber vergleichen</span></button>`}
        ${emailCard(p)}
      </div>
    </section>
    <section class="document-section"><h2>Aktuelle Unterlagen</h2><div class="document-grid">
      ${documentLink('Produktinformation','Aktuelle Produktinformationen und Einwirkzeiten',productDocUrl(p,'pif'),'📄')}
      ${documentLink('Sicherheitsdatenblatt','Aktuelle Sicherheitsinformationen',productDocUrl(p,'sdb'),'🛡️')}
      ${documentLink('Betriebsanweisung','Dokumente für den sicheren Umgang',productDocUrl(p,'ba'),'📋')}
      ${documentLink('Produktbild','Aktuelle Bilddaten herunterladen',OFFICIAL.images,'🖼️')}
    </div></section>
  </main>`;
}


function emailCard(p) {
  const chips = [
    ['price','Preis', !state.customerMode && !inMesseContext()],
    ['sheet','Produktdatenblatt', true],
    ['safety','Sicherheitsdatenblatt', true],
    ['ba','Betriebsanweisung', true],
    ['muster','Muster', true]
  ];
  const count = state.favorites.length;
  return `<div class="email-card">
    <span>Kundeninfo per E-Mail${count ? ` · ${count} mit ★ markiert` : ''}</span>
    <div class="email-chips">${chips.map(([key,label,available]) => available ? `<button class="filter-chip email-chip ${state.emailInclude[key]?'active':''}" data-email-toggle="${key}">${label}</button>` : '').join('')}</div>
    <button class="primary-button compact" data-action="send-email" ${count?'':'disabled'}>${icon('talk')}<span>Info per E-Mail senden${count>1?` (${count} Produkte)`:''}</span></button>
    ${count===0 ? '<small class="muted-copy">Markieren Sie zuerst mindestens ein Produkt mit dem Stern (★).</small>' : ''}
  </div>`;
}

function favoriteEntries() {
  return state.favorites.map(f => ({...f, product: PRODUCTS.find(p => p.id === f.id)})).filter(e => e.product);
}

function buildStarredProductsEmail() {
  const entries = favoriteEntries();
  const inc = state.emailInclude;
  const lines = [`Hallo Team,`, ``, `bitte nachstehende Informationen${inc.muster ? ' an den Kunden senden und die vermerkten Muster bereitstellen' : ' an den Kunden senden'}:`, ``];
  entries.forEach(({product: p, size}) => {
    const price = resolvePrice(p, size);
    lines.push(`PRODUKT: ${p.name}`, `Artikelnummer: ${resolveArtNr(p, size)}`, `Gebinde: ${size}`);
    if (inc.price && !state.customerMode && !inMesseContext() && price !== undefined && price !== null && price !== '') {
      lines.push(`Preis (${state.priceList}): ${money(price)} zzgl. MwSt.`);
      const per = perUnitLabel(p, size);
      if (per) lines.push(`Umgerechnet: ${per}`);
    }
    if (inc.sheet) lines.push(`PRODUKTDATENBLATT (PIF): ${productDocUrl(p,'pif')}`);
    if (inc.safety) lines.push(`SICHERHEITSDATENBLATT: ${productDocUrl(p,'sdb')}`);
    if (inc.ba) lines.push(`BETRIEBSANWEISUNG (BA): ${productDocUrl(p,'ba')}`);
    if (inc.muster) lines.push(`MUSTER: bitte ein Muster (${size}) an den Kunden senden`);
    lines.push('');
  });
  lines.push('Danke und Grüße');
  const subject = entries.length === 1 ? `Produktinformation${inc.muster ? ' & Musteranfrage' : ''} ${entries[0].product.name} – Dr. Schumacher` : `Produktinformationen${inc.muster ? ' & Musteranfrage' : ''} (${entries.length} Produkte) – Dr. Schumacher`;
  return { subject, body: lines.join('\n') };
}

function openMailto(subject, body, to='') {
  const a = document.createElement('a');
  a.href = `mailto:${to}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
}

function sendStarredProductsEmail() {
  if (!state.favorites.length) return;
  const {subject, body} = buildStarredProductsEmail();
  openMailto(subject, body, innendienstEmail());
}

async function copyEmailText(subject, body, button) {
  const text = `Betreff: ${subject}\n\n${body}`;
  try {
    await navigator.clipboard.writeText(text);
  } catch (e) {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e2) {}
    ta.remove();
  }
  if (button) {
    const original = button.innerHTML;
    button.innerHTML = `${icon('star')}<span>Kopiert!</span>`;
    button.disabled = true;
    setTimeout(() => { button.innerHTML = original; button.disabled = false; }, 1800);
  }
}

const ADVISOR_CATEGORIES = [
  {key:'surface', label:'Fläche', sub:'Desinfektion & Reinigung'},
  {key:'hands', label:'Hände & Haut', sub:'Händedesinfektion & Pflege'},
  {key:'instruments', label:'Instrumente', sub:'Aufbereitung & Desinfektion'},
  {key:'application', label:'Applikation', sub:'Spendersysteme & Zubehör'}
];

const ADVISOR_SUBTYPES = {
  surface: [
    {key:'liquid', label:'Flächendesinfektion (Konzentrat/gebrauchsfertig)', match:p=>/Flächendesinfektion|Desinfektionsmittel/.test(p.kind)},
    {key:'wipes', label:'Desinfektionstücher', match:p=>/tücher/i.test(p.kind)},
    {key:'dispenser', label:'Tuchspendersystem', match:p=>p.kind==='Vliestuchspendersysteme'}
  ],
  hands: [
    {key:'handdis', label:'Händedesinfektion', match:p=>/Händedesinfektion/.test(p.kind)},
    {key:'skindis', label:'Hautdesinfektion (OP/Injektion)', match:p=>p.kind==='Hautdesinfektion'},
    {key:'care', label:'Hautpflege & Hautschutz', match:p=>/Hautschutz/.test(p.kind)},
    {key:'remediation', label:'Sanierung (Schimmel etc.)', match:p=>p.kind==='Sanierung'}
  ],
  instruments: [
    {key:'manual', label:'Manuelle Aufbereitung', match:p=>/Manuelle|Instrumentendesinfektion/.test(p.kind)},
    {key:'machine', label:'Maschinelle Aufbereitung', match:p=>/Maschinelle/.test(p.kind)}
  ],
  application: [
    {key:'wall', label:'Wandspender', match:p=>p.kind==='Wandspender & Zubehör'},
    {key:'wipesdisp', label:'Tuchspender & Zubehör', match:p=>/Vliestuchspender|Spender und Applikation/.test(p.kind)},
    {key:'holder', label:'Halter & Dosierhilfen', match:p=>p.kind==='Halter, Dosierhilfen & Zubehör'}
  ]
};

function advisorRefinement(category, subtype) {
  const text = p => `${p.kind} ${p.summary} ${p.facts.join(' ')}`;
  if (category === 'surface' && (subtype === 'liquid' || subtype === 'wipes')) {
    return {question:'Was ist besonders wichtig?', options:[
      {value:'routine', label:'Routineanwendung', match:()=>true},
      {value:'material', label:'Empfindliche Materialien', match:p=>/material|empfindlich|schonend/i.test(text(p))},
      {value:'ausbruch', label:'Ausbruchsfall / breites Spektrum', match:p=>p.spectrum.includes('viruzid')||p.spectrum.includes('sporizid')},
      {value:'alkoholisch', label:'Alkoholisch gewünscht', match:p=>/alkoholisch|schnelldesinfektion/i.test(text(p))},
      {value:'alkoholfrei', label:'Alkoholfrei gewünscht', match:p=>/alkoholfrei|oxidativ|pulver/i.test(text(p))}
    ]};
  }
  if (category === 'hands' && subtype === 'handdis') {
    return {question:'Was ist besonders wichtig?', options:[
      {value:'routine', label:'Routineanwendung', match:()=>true},
      {value:'sensibel', label:'Sensible Haut / parfümfrei', match:p=>/parfüm|sensib/i.test(text(p))},
      {value:'ausbruch', label:'Ausbruchsfall (Noro/Adeno/Rota)', match:p=>p.spectrum.includes('viruzid')},
      {value:'gel', label:'Gelform gewünscht', match:p=>/gel/i.test(p.kind)}
    ]};
  }
  if (category === 'hands' && subtype === 'skindis') {
    return {question:'Gefärbt oder farblos?', options:[
      {value:'egal', label:'Egal', match:()=>true},
      {value:'gefaerbt', label:'Gefärbt', match:p=>/GEFÄRBT/i.test(p.name)},
      {value:'farblos', label:'Farblos', match:p=>!/GEFÄRBT/i.test(p.name)}
    ]};
  }
  if (category === 'hands' && subtype === 'care') {
    return {question:'Welche Produktform suchen Sie?', options:[
      {value:'wasch', label:'Waschlotion', match:p=>/waschlotion/i.test(text(p))},
      {value:'creme', label:'Creme / Emulsion', match:p=>/crem|cream|emulsion/i.test(`${p.name} ${text(p)}`) && !/wipes/i.test(p.name)},
      {value:'tuch', label:'Pflegetücher', match:p=>/wipes/i.test(p.name)},
      {value:'spezial', label:'Spezialpflege (Ölbad, Gel)', match:p=>/ölbad|vital gel/i.test(p.name)}
    ]};
  }
  if (category === 'instruments' && subtype === 'manual') {
    return {question:'Reinigung, Desinfektion oder beides?', options:[
      {value:'reinigung', label:'Nur Reinigung', match:p=>!(p.spectrum && p.spectrum.length)},
      {value:'kombi', label:'Reinigung + Desinfektion', match:p=>p.spectrum && p.spectrum.length>0},
      {value:'sporizid', label:'Sporizid / Ausbruchsfall', match:p=>p.spectrum && p.spectrum.includes('sporizid')}
    ]};
  }
  if (category === 'instruments' && subtype === 'machine') {
    const names = {
      reinigung: ['THERMOSHIELD® FLEX','XTREME'],
      desinfektion: ['THERMOSHIELD®','DESINFEKTANT','THERMOSHIELD® NR'],
      neutralisation: ['THERMOSHIELD® BASIX','THERMOSHIELD® C','THERMOSHIELD® P','THERMOSHIELD® SHINE','THERMO CLEAR','THERMO ALKA CLEAR'],
      pflege: ['SPEZIAL ÖLSPRAY']
    };
    return {question:'Welcher Prozessschritt wird benötigt?', options:[
      {value:'reinigung', label:'Reinigung', match:p=>names.reinigung.includes(p.name)},
      {value:'desinfektion', label:'Desinfektion (Endoskope)', match:p=>names.desinfektion.includes(p.name)},
      {value:'neutralisation', label:'Neutralisation & Klarspülung', match:p=>names.neutralisation.includes(p.name)},
      {value:'pflege', label:'Pflege & Schmierung', match:p=>names.pflege.includes(p.name)}
    ]};
  }
  if (category === 'application' && subtype === 'wall') {
    return {question:'Touchless (berührungslos) gewünscht?', options:[
      {value:'egal', label:'Egal', match:()=>true},
      {value:'touchless', label:'Ja, touchless', match:p=>/touchless/i.test(p.name)},
      {value:'manuell', label:'Nein, manuell', match:p=>!/touchless/i.test(p.name)}
    ]};
  }
  return null;
}

function advisorScreen() {
  const a = state.advisor;
  const categoryDef = ADVISOR_CATEGORIES.find(c => c.key === a.category);
  const subtypeDef = a.category ? (ADVISOR_SUBTYPES[a.category]||[]).find(s => s.key === a.subtype) : null;
  const refinement = (a.category && a.subtype) ? advisorRefinement(a.category, a.subtype) : null;
  const done = !!a.category && !!a.subtype && (!refinement || !!a.need);

  const trailParts = [];
  if (categoryDef) trailParts.push(['category', categoryDef.label]);
  if (a.subtype && subtypeDef) trailParts.push(['subtype', subtypeDef.label]);
  if (refinement && a.need) { const opt = refinement.options.find(o => o.value === a.need); if (opt) trailParts.push(['need', opt.label]); }
  const trail = trailParts.map(([k,l]) => `<button class="advisor-chip" data-advisor-edit="${k}">${escapeHtml(l)}</button>`).join('<span class="advisor-arrow">→</span>');
  const totalSteps = refinement ? 3 : (a.category && a.subtype) ? 2 : 3;
  const answeredCount = trailParts.length;
  const progressDots = Array.from({length: totalSteps}).map((_,i) => `<span class="advisor-dot ${i < answeredCount ? 'done' : (i===answeredCount ? 'current' : '')}"></span>`).join('');

  if (done) {
    const results = advisorResults();
    return `<main class="page advisor-page">
      <div class="section-heading"><div><span class="eyebrow">Geführte Auswahl</span><h1>Produktberater</h1><p>Empfehlung auf Basis Ihrer Angaben. Ersetzt keine verbindliche Produktinformation.</p></div><button class="secondary-button" data-action="reset-advisor">Neu starten</button></div>
      <div class="advisor-progress">${progressDots}</div>
      ${trail ? `<div class="advisor-trail">${trail}</div>` : ''}
      <section class="advisor-results"><div class="section-heading"><div><span class="eyebrow">Empfehlung</span><h2>${results.length ? 'Passende Produkte' : 'Keine Treffer für diese Kombination'}</h2></div></div><div class="product-list">${results.map(productCard).join('')}</div><div class="advisor-note">Die Auswahl basiert auf den hinterlegten Kurzmerkmalen. Vor einer verbindlichen Empfehlung müssen aktuelle Produktinformation, Einwirkzeiten, Freigaben und Materialverträglichkeit geprüft werden.</div></section>
    </main>`;
  }

  let question, tilesHtml;
  if (!a.category) {
    question = 'Was ist die Indikation? Wo soll das Produkt eingesetzt werden?';
    tilesHtml = `<div class="category-grid">${ADVISOR_CATEGORIES.map(c => `<button class="category-card ${c.key}" data-advisor="category" data-value="${c.key}"><span class="category-icon">${icon(c.key)}</span><span><strong>${c.label}</strong><small>${c.sub}</small></span><b>›</b></button>`).join('')}</div>`;
  } else if (!a.subtype) {
    question = 'Welche Produktart suchen Sie?';
    const opts = ADVISOR_SUBTYPES[a.category] || [];
    tilesHtml = `<div class="answer-grid wizard">${opts.map(o => `<button class="answer-button" data-advisor="subtype" data-value="${o.key}">${o.label}</button>`).join('')}</div>`;
  } else {
    question = refinement.question;
    tilesHtml = `<div class="answer-grid wizard">${refinement.options.map(o => `<button class="answer-button" data-advisor="need" data-value="${o.value}">${o.label}</button>`).join('')}</div>`;
  }

  return `<main class="page advisor-page">
    <div class="section-heading"><div><span class="eyebrow">Frage ${answeredCount+1} von ${totalSteps}</span><h1>${question}</h1></div>${answeredCount>0 ? '<button class="secondary-button" data-action="advisor-back">Zurück</button>' : ''}</div>
    <div class="advisor-progress">${progressDots}</div>
    ${trail ? `<div class="advisor-trail">${trail}</div>` : ''}
    <section class="advisor-card">${tilesHtml}</section>
  </main>`;
}
function advisorBack() {
  const order = ['category','subtype','need'];
  for (let i = order.length - 1; i >= 0; i--) {
    if (state.advisor[order[i]]) { state.advisor[order[i]] = ''; break; }
  }
  render();
}
function advisorEdit(key) {
  const order = ['category','subtype','need'];
  order.slice(order.indexOf(key)).forEach(k => state.advisor[k] = '');
  render();
}

function advisorResults() {
  const a = state.advisor;
  if (!a.category || !a.subtype) return [];
  const subtypeDef = (ADVISOR_SUBTYPES[a.category]||[]).find(s => s.key === a.subtype);
  if (!subtypeDef) return [];
  let list = PRODUCTS.filter(p => p.category === a.category && subtypeDef.match(p));
  const refinement = advisorRefinement(a.category, a.subtype);
  if (refinement && a.need) {
    const opt = refinement.options.find(o => o.value === a.need);
    if (opt) list = list.filter(opt.match);
  }
  return list.slice(0,8);
}

function recentScreen() {
  const list = state.recent.map(id => PRODUCTS.find(p => p.id===id)).filter(Boolean);
  return `<main class="page products-page"><div class="section-heading"><div><span class="eyebrow">Schnellzugriff</span><h1>Zuletzt angesehen</h1></div><span class="result-count">${list.length}</span></div><div class="product-list">${list.map(productCard).join('') || '<div class="empty-state"><h2>Noch kein Verlauf</h2><p>Geöffnete Produkte erscheinen automatisch hier.</p></div>'}</div></main>`;
}

function compareScreen() {
  const selected = state.compareIds.map(id => PRODUCTS.find(p => p.id === id)).filter(Boolean);
  return `<main class="page compare-page">
    <div class="section-heading"><div><span class="eyebrow">Gesprächshilfe</span><h1>Produktvergleich</h1><p>Wählen Sie bis zu drei Produkte. Die Übersicht hilft bei der Präsentation, ersetzt aber keine aktuelle Produktinformation.</p></div><span class="result-count">${selected.length}/3</span></div>
    <section class="compare-picker"><h2>Produkte auswählen</h2><div class="compare-product-grid">${PRODUCTS.map(p => `<button class="compare-choice ${state.compareIds.includes(p.id)?'active':''}" data-compare="${p.id}"><span style="--dot:${p.color}"></span><div><strong>${p.name}</strong><small>${p.kind}</small></div><b>${state.compareIds.includes(p.id)?'✓':'+'}</b></button>`).join('')}</div></section>
    ${selected.length ? `<section class="comparison-wrap"><div class="comparison-grid">${selected.map(compareColumn).join('')}</div></section>
    <section class="pitch-card"><span class="eyebrow">Formulierungsvorschlag</span><h2>So können Sie den Vergleich erklären</h2><p>${comparisonPitch(selected)}</p><button class="secondary-button" data-action="copy-pitch">Text kopieren</button></section>` : '<div class="empty-state"><h2>Noch kein Produkt ausgewählt</h2><p>Tippen Sie oben auf bis zu drei Produkte.</p></div>'}
  </main>`;
}

function compareColumn(p) {
  const price = resolvePrice(p);
  return `<article class="compare-column"><div class="compare-head" style="--product-color:${p.color}"><span>${p.category==='hands'?'✋':p.category==='surface'?'▦':p.category==='instruments'?'✂':'▣'}</span><h2>${p.name}</h2><small>${p.kind}</small></div><div class="compare-line"><b>Wirkspektrum</b><div class="badges">${p.spectrum.map(spectrumBadge).join('') || '<span>–</span>'}</div></div><div class="compare-line"><b>Stärken</b><ul>${p.facts.slice(0,3).map(f=>`<li>${f}</li>`).join('')}</ul></div><div class="compare-line"><b>Gebinde</b><span>${p.sizes.join(', ')}</span></div><div class="compare-line"><b>${state.customerMode?'Preis':'Preis '+state.priceList}</b><strong>${state.customerMode?'verborgen':money(price)}</strong></div><button class="primary-button compact" data-product="${p.id}">Produkt öffnen</button></article>`;
}

function comparisonPitch(list) {
  if (list.length === 1) return `${list[0].name} eignet sich besonders, wenn ${list[0].facts[0].toLowerCase()}. Die verbindlichen Einsatzbedingungen prüfen wir direkt in der aktuellen Produktinformation.`;
  const names = list.map(p=>p.name).join(', ');
  return `Wir vergleichen ${names}. Entscheidend sind Einsatzbereich, benötigtes Wirkspektrum, Materialverträglichkeit und gewünschte Gebindeform. Anschließend prüfen wir die verbindlichen Einwirkzeiten und Freigaben in den aktuellen offiziellen Unterlagen.`;
}

function saveVsCompare(patch) {
  state.vsCompare = {...state.vsCompare, ...patch};
  localStorage.setItem('vsCompare', JSON.stringify(state.vsCompare));
}

function vsCalculation() {
  const v = state.vsCompare;
  const product = PRODUCTS.find(p => p.id === v.productId) || null;
  const size = product && v.size && product.sizes.includes(v.size) ? v.size : (product ? product.sizes[0] : '');
  const rawOurPrice = product ? resolvePrice(product, size) : null;
  const ourPrice = (rawOurPrice === '' || rawOurPrice == null) ? null : Number(rawOurPrice);
  const units = size ? unitsInSize(size) : null;
  const ourPerUnit = (ourPrice != null && units) ? ourPrice / units : null;
  const compPrice = v.competitorPrice === '' ? null : Number(v.competitorPrice);
  const compPerUnit = (compPrice != null && units) ? compPrice / units : null;
  const consumption = v.annualUnits === '' ? null : Number(v.annualUnits);
  const ourAnnual = (consumption != null) ? (units ? consumption * (ourPerUnit ?? NaN) : (ourPrice != null ? consumption * ourPrice : null)) : null;
  const compAnnual = (consumption != null && compPrice != null) ? (units ? consumption * (compPerUnit ?? NaN) : consumption * compPrice) : null;
  const savings = (ourAnnual != null && compAnnual != null && !isNaN(ourAnnual) && !isNaN(compAnnual)) ? compAnnual - ourAnnual : null;
  const ready = !!(product && ourPrice != null && compPrice != null && consumption != null);
  return {product, size, ourPrice, units, ourPerUnit, compPrice, compPerUnit, consumption, ourAnnual, compAnnual, savings, ready};
}


function summaryScreen(){
  const chosen=favoriteEntries();
  const query=(state.summaryQuery||'').toLowerCase();
  const pickable=query?PRODUCTS.filter(p=>`${p.name} ${p.kind}`.toLowerCase().includes(query)):PRODUCTS;
  return `<main class="page lists-page"><div class="section-heading"><div><span class="eyebrow">Kundengespräch</span><h1>Kundenzusammenfassung</h1><p>Alle Produkte, die Sie unterwegs mit dem Stern (★) markiert haben, erscheinen automatisch hier – je Gebinde einzeln, falls Sie z. B. mehrere Packungsgrößen besprochen haben. Daraus erstellt die App eine kurze Vorteils-Zusammenfassung, die Sie direkt per E-Mail an den Kunden senden können.</p></div></div>
  <section class="offer-config">
    <label>Anrede<input id="summaryCustomer" value="${escapeHtml(state.summaryCustomer)}" placeholder="z. B. Sehr geehrter Herr Müller"></label>
    <label>Anlass des Gesprächs<input id="summaryOccasion" value="${escapeHtml(state.summaryOccasion)}" placeholder="z. B. unser heutiges Teams-Meeting"></label>
  </section>
  <section class="summary-price-toggle">
    <span>E-Mail-Inhalt</span>
    <div class="price-toggle-row">
      <button class="filter-chip ${!state.summaryIncludePrices?'active':''}" data-summary-prices="false">Nur Zusammenfassung (ohne Preise)</button>
      ${state.customerMode ? '' : `<button class="filter-chip ${state.summaryIncludePrices?'active':''}" data-summary-prices="true">Mit Preisen (${escapeHtml(state.priceList)})</button>`}
    </div>
    ${state.customerMode ? '<small class="muted-copy">Preise sind im Kundenmodus verborgen.</small>' : ''}
  </section>
  <section class="list-builder">
    <div><h2>Mit Stern markiert (${chosen.length})</h2><div class="product-list">${chosen.map(e=>summaryChosenCard(e)).join('')||'<div class="empty-state"><h2>Noch keine Produkte markiert</h2><p>Tippen Sie im Gespräch bei einem Produkt auf den Stern, oder wählen Sie rechts direkt aus.</p></div>'}</div></div>
    <div><h2>Weitere Produkte markieren</h2><label class="search-box summary-search">${icon('search')}<input id="summarySearch" value="${escapeHtml(state.summaryQuery||'')}" placeholder="Produkt suchen"></label><div class="quick-product-list">${pickable.map(p=>summaryProductCard(p)).join('') || '<p class="muted-copy">Kein Produkt gefunden.</p>'}</div></div>
  </section>
  <div class="offer-actions summary-send"><button class="primary-button compact" data-action="send-summary" ${chosen.length?'':'disabled'}>${icon('talk')}<span>An Kunden senden</span></button></div>
  </main>`;
}
function summaryProductCard(p){const selected=state.favorites.some(f=>f.id===p.id);return `<article class="mini-product"><span style="--dot:${p.color}"></span><div><strong>${p.name}</strong><small>${p.kind}</small></div><button data-favorite="${p.id}">${selected?'−':'+'}</button></article>`}
function summaryChosenCard(entry){
  const p=entry.product, size=entry.size;
  const sizePicker=p.sizes.length>1
    ? `<select class="offer-input summary-size" data-favorite-id="${p.id}" data-favorite-old-size="${escapeHtml(size)}" aria-label="Gebinde">${p.sizes.map(s=>`<option ${s===size?'selected':''}>${escapeHtml(s)}</option>`).join('')}</select>`
    : `<small>${escapeHtml(size||'')}</small>`;
  return `<article class="mini-product summary-chosen-product"><span style="--dot:${p.color}"></span><div><strong>${p.name}</strong><small>${p.kind}</small>${sizePicker}</div><button data-favorite="${p.id}" data-favorite-size="${escapeHtml(size)}">−</button></article>`;
}
function buildCustomerSummaryEmail(){
  const entries=favoriteEntries();
  const salutation=state.summaryCustomer.trim()||'Sehr geehrte Damen und Herren';
  const occasion=state.summaryOccasion.trim()||'unser heutiges Gespräch';
  const lines=[
    `${salutation},`,
    ``,
    `vielen Dank für ${occasion}. Es freut uns, Ihnen im Anschluss die folgenden Informationen zu den besprochenen Produkten zukommen zu lassen – mit den Eigenschaften, die für Sie den größten Mehrwert bieten:`,
    ``
  ];
  const showPrices = state.summaryIncludePrices && !state.customerMode;
  entries.forEach(({product: p, size})=>{
    lines.push(`${p.name.toUpperCase()}${size ? ' – ' + size : ''}`, p.kind);
    if (showPrices) {
      const price = resolvePrice(p, size);
      if (price !== undefined && price !== null && price !== '') lines.push(`Preis (${state.priceList}): ${money(price)} zzgl. MwSt.`);
    }
    lines.push('Ihre Vorteile auf einen Blick:');
    p.facts.forEach(f=>lines.push(`✓ ${f}`));
    lines.push('');
  });
  lines.push('Für Rückfragen stehen wir Ihnen jederzeit gerne zur Verfügung.','','Mit freundlichen Grüßen');
  return {subject:`Zusammenfassung unseres Gesprächs – Dr. Schumacher`, body:lines.join('\n')};
}
function sendCustomerSummaryEmail(){
  if(!state.favorites.length)return;
  const {subject,body}=buildCustomerSummaryEmail();
  openMailto(subject,body);
}

function competitionScreen(){
  const v = state.vsCompare;
  const calc = vsCalculation();
  const unitWord = calc.units ? 'Tuch' : 'Packung';
  const consumptionLabel = calc.units ? 'Verbrauch (Tücher/Jahr)' : 'Verbrauch (Packungen/Jahr)';
  return `<main class="page vs-page">
    <div class="section-heading no-print"><div><span class="eyebrow">Kundengespräch</span><h1>Wettbewerbsvergleich</h1><p>Aktuellen Preis des Kunden eintragen – die App rechnet Jahreskosten und Ersparnis sofort aus.</p></div></div>
    <section class="vs-config no-print">
      <label>Unser Produkt<select id="vsProduct"><option value="">Bitte wählen…</option>${PRODUCTS.map(p=>`<option value="${p.id}" ${p.id===v.productId?'selected':''}>${p.name}</option>`).join('')}</select></label>
      ${calc.product ? `<label>Gebinde<select id="vsSize">${calc.product.sizes.map(s=>`<option ${s===calc.size?'selected':''}>${s}</option>`).join('')}</select></label>` : '<div></div>'}
      <label>Wettbewerber<input id="vsCompetitorName" value="${escapeHtml(v.competitorName)}" placeholder="Hersteller / Produktname"></label>
      ${calc.product && competitorSuggestions(calc.product.kind).length ? `<small class="muted-copy wide vs-competitor-hint">Übliche Wettbewerber für „${escapeHtml(calc.product.kind)}“: ${competitorSuggestions(calc.product.kind).map(escapeHtml).join(' · ')}</small>` : ''}
      <label>Kundenpreis (${escapeHtml(calc.size || 'gleiches Gebinde')})<input id="vsCompetitorPrice" type="text" inputmode="decimal" value="${escapeHtml(v.competitorPrice)}" placeholder="z. B. 9,45"></label>
      <label class="wide">${consumptionLabel}<input id="vsAnnualUnits" type="text" inputmode="numeric" value="${escapeHtml(v.annualUnits)}" placeholder="z. B. 10000"></label>
    </section>
    ${!calc.product ? '<div class="empty-state no-print"><h2>Produkt wählen, um zu starten</h2><p>Wählen Sie oben unser Produkt, tragen Sie den Kundenpreis des Wettbewerbers ein und ergänzen Sie den Jahresverbrauch.</p></div>' : `
    <section class="vs-sheet">
      <div class="offer-brand"><img src="public/assets/dr-schumacher-logo.png" alt="Dr. Schumacher"><div><span>Wirtschaftlichkeitsvergleich</span><strong>${escapeHtml(calc.product.name)} vs. ${escapeHtml(v.competitorName || 'Wettbewerber')}</strong><small>Preisliste ${escapeHtml(state.priceList)} · ${new Date().toLocaleDateString('de-DE')}</small></div></div>
      <div class="offer-table-wrap"><table class="offer-table vs-table"><thead><tr><th>Kennzahl</th><th>Unser Produkt</th><th>Wettbewerber</th><th>Vorteil</th></tr></thead><tbody>
        <tr><td>Produkt</td><td>${escapeHtml(calc.product.name)}</td><td>${escapeHtml(v.competitorName || '–')}</td><td></td></tr>
        <tr><td>Gebinde</td><td>${escapeHtml(calc.size)}</td><td>${escapeHtml(calc.size)}</td><td></td></tr>
        <tr><td>Preis</td><td>${calc.ourPrice!=null?money(calc.ourPrice):'–'}</td><td>${calc.compPrice!=null?money(calc.compPrice):'–'}</td><td>${(calc.ourPrice!=null&&calc.compPrice!=null)?money(calc.compPrice-calc.ourPrice):''}</td></tr>
        ${calc.units?`<tr><td>Preis pro ${unitWord}</td><td>${calc.ourPerUnit!=null?moneyPerUnit(calc.ourPerUnit):'–'}</td><td>${calc.compPerUnit!=null?moneyPerUnit(calc.compPerUnit):'–'}</td><td>${(calc.ourPerUnit!=null&&calc.compPerUnit!=null)?moneyPerUnit(calc.compPerUnit-calc.ourPerUnit):''}</td></tr>`:''}
        <tr><td>Verbrauch/Jahr</td><td colspan="2">${calc.consumption!=null?calc.consumption.toLocaleString('de-DE')+' '+unitWord+(calc.consumption===1?'':'er'):'–'}</td><td></td></tr>
        <tr><td>Jahreskosten</td><td>${calc.ourAnnual!=null?money(calc.ourAnnual):'–'}</td><td>${calc.compAnnual!=null?money(calc.compAnnual):'–'}</td><td class="line-total">${calc.savings!=null?money(calc.savings):''}</td></tr>
      </tbody></table></div>
      ${calc.savings!=null ? `<div class="vs-result ${calc.savings>=0?'positive':'negative'}">Ergebnis: ${money(Math.abs(calc.savings))} ${calc.savings>=0?'Ersparnis':'Mehrkosten'} pro Jahr bei ${calc.consumption.toLocaleString('de-DE')} ${unitWord}${calc.consumption===1?'':'ern'} – Berechnung auf Basis der eingegebenen Kundenpreise.</div>` : '<div class="empty-state no-print"><p>Kundenpreis und Jahresverbrauch eintragen, um das Ergebnis zu berechnen.</p></div>'}
      <div class="offer-actions no-print"><button class="primary-button compact" data-action="print-vs" ${calc.ready?'':'disabled'}>Drucken / als PDF speichern</button></div>
      <div class="offer-disclaimer">Berechnung auf Basis der vom Nutzer eingegebenen Kundenpreise und Verbrauchsangaben. Keine Gleichwertigkeits- oder Freigabeerklärung. Anwendung, Materialverträglichkeit, Wirkbereich und Einwirkzeit bitte anhand der aktuellen Produktunterlagen prüfen.</div>
    </section>`}
  </main>`;
}

function talkScreen(){
 const product=PRODUCTS.find(p=>p.id===state.talkProduct)||PRODUCTS[0]; if(!state.talkProduct)state.talkProduct=product.id;
 const situations=['Kurzvorstellung','Bedarf ermitteln','Einwand: zu teuer','Abschlussfrage'];
 return `<main class="page talk-page"><div class="section-heading"><div><span class="eyebrow">Kundengespräch</span><h1>Gesprächsassistent</h1><p>Produkt und Situation auswählen. Die Formulierung lässt sich direkt kopieren.</p></div></div><section class="talk-config"><label>Produkt<select id="talkProduct">${PRODUCTS.map(p=>`<option value="${p.id}" ${p.id===product.id?'selected':''}>${p.name}</option>`).join('')}</select></label><label>Gesprächssituation<select id="talkSituation">${situations.map(x=>`<option ${x===state.talkSituation?'selected':''}>${x}</option>`).join('')}</select></label></section><section class="pitch-card"><span class="eyebrow">Formulierungsvorschlag</span><h2>${product.name}</h2><p class="talk-output">${buildTalkText()}</p><button class="primary-button compact" data-action="copy-talk">Text kopieren</button></section><section class="info-card"><h2>Gesprächsanker</h2><ul>${product.facts.map(f=>`<li><span>✓</span>${f}</li>`).join('')}</ul><div class="info-warning">Aussagen vor Verwendung mit der aktuellen offiziellen Produktinformation abgleichen.</div></section></main>`;
}
function buildTalkText(){const p=PRODUCTS.find(x=>x.id===state.talkProduct)||PRODUCTS[0];const fact=p.facts[0].replace(/^[A-ZÄÖÜ]/,m=>m.toLowerCase());if(state.talkSituation==='Bedarf ermitteln')return `Damit ich Ihnen das passende Produkt empfehlen kann: Auf welchen Flächen oder in welchem Prozess möchten Sie es einsetzen, welches Wirkspektrum benötigen Sie und gibt es empfindliche Materialien oder besondere Vorgaben? Anschließend prüfen wir gemeinsam, ob ${p.name} passt.`;if(state.talkSituation==='Einwand: zu teuer')return `Ich verstehe, dass der Preis wichtig ist. Bei ${p.name} sollten wir deshalb nicht nur den Gebindepreis betrachten, sondern Anwendung, Verbrauch, Prozessaufwand und Produktausnutzung. Besonders relevant ist, dass ${fact}. Lassen Sie uns die Kosten pro Anwendung vergleichen.`;if(state.talkSituation==='Abschlussfrage')return `Auf Basis Ihrer Anforderungen halte ich ${p.name} für eine passende Option. Sollen wir die aktuelle Produktinformation gemeinsam prüfen und anschließend ein Muster beziehungsweise ein konkretes Angebot für das passende Gebinde vorbereiten?`;return `${p.name} ist für ${p.kind.toLowerCase()} vorgesehen. Der zentrale Mehrwert: ${fact}. Entscheidend ist, dass wir das Produkt passend zu Ihrem Einsatzbereich und dem benötigten Wirkspektrum auswählen. Die verbindlichen Einwirkzeiten und Freigaben prüfen wir direkt in der aktuellen Produktinformation.`}


function quoteKey(id, size) { return id + '__' + size; }

function offerScreen() {
  const entries = favoriteEntries();
  let subtotal = 0;
  const rows = entries.map(({product: p, size}) => {
    const key = quoteKey(p.id, size);
    const saved = state.quoteItems[key] || {};
    const quantity = Math.max(1, Number(saved.quantity) || 1);
    const discount = Math.min(100, Math.max(0, Number(saved.discount) || 0));
    const rawPrice = resolvePrice(p, size);
    const unitPrice = rawPrice === '' || rawPrice == null ? null : Number(rawPrice);
    const lineTotal = unitPrice == null ? null : unitPrice * quantity * (1 - discount / 100);
    if (lineTotal != null) subtotal += lineTotal;
    return `<tr>
      <td><strong>${p.name}</strong><small>${p.kind}<br>Art.-Nr. ${resolveArtNr(p, size)} · ${escapeHtml(size)}</small></td>
      <td><input class="offer-input quantity" data-quote-item="${key}" data-field="quantity" type="text" inputmode="numeric" value="${quantity}"></td>
      <td><input class="offer-input discount" data-quote-item="${key}" data-field="discount" type="text" inputmode="decimal" value="${discount}"><span class="unit">%</span></td>
      <td class="offer-price">${state.customerMode ? 'ausgeblendet' : money(unitPrice)}</td>
      <td class="offer-price line-total">${state.customerMode ? 'ausgeblendet' : money(lineTotal)}</td>
    </tr>`;
  }).join('');
  const vat = subtotal * 0.19;
  const total = subtotal + vat;
  const validUntil = state.quoteValidUntil || new Date(Date.now()+14*86400000).toISOString().slice(0,10);
  return `<main class="page offer-page"><div class="section-heading no-print"><div><span class="eyebrow">Angebotsentwurf</span><h1>Kundenübersicht & Kalkulation</h1><p>Erstellt aus den mit ★ markierten Produkten.</p></div></div>
    <section class="offer-config no-print"><label>Kunde / Einrichtung<input id="quoteCustomer" value="${escapeHtml(state.quoteCustomer)}" placeholder="z. B. Klinikum Dortmund"></label><label>Ansprechpartner<input id="quoteContact" value="${escapeHtml(state.quoteContact)}" placeholder="Name oder Funktion"></label><label>Gültig bis<input id="quoteValidUntil" type="date" value="${escapeHtml(validUntil)}"></label><label class="wide">Notiz<textarea id="quoteNote" placeholder="Ziel, nächste Schritte oder besondere Anforderungen">${escapeHtml(state.quoteNote)}</textarea></label><div class="offer-actions wide"><button class="secondary-button" data-action="customer-mode">${state.customerMode?'Preise wieder anzeigen':'Preise für Kunden ausblenden'}</button><button class="secondary-button" data-action="export-offer">CSV für Innendienst</button><button class="secondary-button" data-action="copy-offer" ${entries.length?'':'disabled'}>${icon('copy')}<span>Text kopieren</span></button><button class="secondary-button" data-action="email-offer" ${entries.length?'':'disabled'}>${icon('talk')}<span>Per E-Mail-Programm öffnen</span></button><button class="primary-button compact" data-action="print-offer">Drucken / als PDF speichern</button></div></section>
    <section class="offer-sheet"><div class="offer-brand"><img src="public/assets/dr-schumacher-logo.png" alt="Dr. Schumacher"><div><span>Angebotsentwurf</span><strong>${escapeHtml(state.quoteCustomer || 'Kundentermin')}</strong><small>${escapeHtml(state.quoteContact || '')}</small></div></div><div class="offer-meta"><span>Markierte Produkte: ${entries.length}</span><span>Preisbasis: ${state.customerMode?'ohne Preise':escapeHtml(state.priceList)}</span><span>Gültig bis: ${new Date(validUntil+'T12:00:00').toLocaleDateString('de-DE')}</span><span>Stand: ${new Date().toLocaleDateString('de-DE')}</span></div>
      ${entries.length ? `<div class="offer-table-wrap"><table class="offer-table offer-calculation"><thead><tr><th>Produkt</th><th>Menge</th><th>Rabatt</th><th>Einzelpreis</th><th>Gesamt</th></tr></thead><tbody>${rows}</tbody></table></div>${state.customerMode?'':`<div class="offer-totals"><div><span>Zwischensumme</span><strong>${money(subtotal)}</strong></div><div><span>zzgl. 19 % MwSt.</span><strong>${money(vat)}</strong></div><div class="grand-total"><span>Gesamtsumme</span><strong>${money(total)}</strong></div></div>`}` : '<div class="empty-state"><h2>Keine Produkte markiert</h2><p>Markieren Sie zuerst Produkte im Gespräch mit dem Stern (★).</p></div>'}
      ${state.quoteNote ? `<div class="offer-note"><strong>Notiz</strong><p>${escapeHtml(state.quoteNote)}</p></div>` : ''}
      <div class="offer-disclaimer">Unverbindlicher interner Angebotsentwurf. Preise, Steuern, Lieferfähigkeit und Konditionen sind vor Versand durch den Innendienst zu prüfen. Verbindliche Anwendung, Einwirkzeiten, Materialverträglichkeit und Sicherheit ausschließlich anhand der aktuellen offiziellen Produktinformationen prüfen.</div>
    </section></main>`;
}


function reportScreen() {
  const r = state.visitReport || {};
  const productNames = favoriteEntries().map(e => `${e.product.name} (${e.size})`).join(', ');
  const reportDate = r.date || new Date().toISOString().slice(0,10);
  const followUp = r.followUp || '';
  const summary = buildCrmSummary({...r, date: reportDate, products: productNames});
  return `<main class="page report-page"><div class="section-heading no-print"><div><span class="eyebrow">Kundentermin dokumentieren</span><h1>Besuchsbericht</h1><p>Die Angaben bleiben lokal auf diesem Gerät und können als CRM-Text oder CSV exportiert werden.</p></div></div>
    <section class="report-form no-print">
      <label>Kunde / Einrichtung<input data-report-field="customer" value="${escapeHtml(r.customer || state.quoteCustomer || '')}" placeholder="z. B. Klinikum Dortmund"></label>
      <label>Datum<input data-report-field="date" type="date" value="${escapeHtml(reportDate)}"></label>
      <label>Ansprechpartner<input data-report-field="contacts" value="${escapeHtml(r.contacts || state.quoteContact || '')}" placeholder="Namen und Funktionen"></label>
      <label>Terminart<select data-report-field="type">${['Erstvorstellung','Produktvorstellung','Feedbackgespräch','Testauswertung','Preisgespräch','Follow-up'].map(x=>`<option ${x===(r.type||'Produktvorstellung')?'selected':''}>${x}</option>`).join('')}</select></label>
      <label class="wide">Ausgangssituation / eingesetzte Produkte<textarea data-report-field="current" placeholder="Was nutzt der Kunde aktuell? Welche Herausforderung besteht?">${escapeHtml(r.current || '')}</textarea></label>
      <label class="wide">Besprochene Produkte<textarea data-report-field="products" placeholder="Mit ★ markierte Produkte oder manuell ergänzen">${escapeHtml(r.products || productNames)}</textarea></label>
      <label class="wide">Feedback und Bedarf<textarea data-report-field="feedback" placeholder="Interesse, Einwände, Anforderungen und Aussagen des Kunden">${escapeHtml(r.feedback || '')}</textarea></label>
      <label>Muster / Unterlagen<select data-report-field="samples">${['Keine','Unterlagen gesendet','Muster übergeben','Test vereinbart','Angebot angefordert'].map(x=>`<option ${x===(r.samples||'Keine')?'selected':''}>${x}</option>`).join('')}</select></label>
      <label>Ergebnis<select data-report-field="result">${['Offen','Interesse vorhanden','Testphase','Angebot erforderlich','Kein aktueller Bedarf','Abschluss vorbereitet'].map(x=>`<option ${x===(r.result||'Offen')?'selected':''}>${x}</option>`).join('')}</select></label>
      <label class="wide">Nächste Schritte<textarea data-report-field="nextSteps" placeholder="Wer macht was bis wann?">${escapeHtml(r.nextSteps || '')}</textarea></label>
      <label>Follow-up am<input data-report-field="followUp" type="date" value="${escapeHtml(followUp)}"></label>
      <label>Verantwortlich<input data-report-field="owner" value="${escapeHtml(r.owner || '')}" placeholder="Name / Außendienst"></label>
      <div class="report-actions wide"><button class="secondary-button" data-action="copy-report">CRM-Text kopieren</button><button class="secondary-button" data-action="export-report">CSV exportieren</button><button class="secondary-button" data-action="save-report">Bericht lokal speichern</button><button class="primary-button compact" data-action="print-report">Drucken / PDF</button></div>
    </section>
    <section class="report-sheet"><div class="offer-brand"><img src="public/assets/dr-schumacher-logo.png" alt="Dr. Schumacher"><div><span>Besuchsbericht</span><strong>${escapeHtml(r.customer || state.quoteCustomer || 'Kundentermin')}</strong><small>${new Date(reportDate+'T12:00:00').toLocaleDateString('de-DE')}</small></div></div><pre class="crm-summary">${escapeHtml(summary)}</pre><div class="offer-disclaimer">Interne Gesprächsdokumentation. Produktbezogene Aussagen vor externer Verwendung anhand der aktuellen offiziellen Unterlagen prüfen.</div></section>
    ${state.savedReports.length ? `<section class="saved-reports no-print"><h2>Lokal gespeicherte Berichte</h2>${state.savedReports.slice(0,5).map((item,i)=>`<button data-load-report="${i}"><strong>${escapeHtml(item.customer || 'Ohne Kundenname')}</strong><small>${escapeHtml(item.date || '')} · ${escapeHtml(item.result || 'Offen')}</small></button>`).join('')}</section>` : ''}
  </main>`;
}


function dashboardScreen() {
  const today = new Date(); today.setHours(0,0,0,0);
  const reports = state.savedReports.map((report,index) => ({...report,index,status:report.status || 'Offen'}));
  const isDone = r => r.status === 'Erledigt';
  const dateValue = r => r.followUp ? new Date(r.followUp+'T12:00:00') : null;
  const overdue = reports.filter(r => !isDone(r) && dateValue(r) && dateValue(r) < today);
  const dueToday = reports.filter(r => !isDone(r) && dateValue(r) && dateValue(r).toDateString() === today.toDateString());
  const upcoming = reports.filter(r => !isDone(r) && dateValue(r) && dateValue(r) > today).sort((a,b)=>dateValue(a)-dateValue(b));
  const openWithoutDate = reports.filter(r => !isDone(r) && !dateValue(r));
  const completed = reports.filter(isDone);
  const taskCard = (r, tone='') => `<article class="follow-card ${tone}"><div><span class="follow-date">${r.followUp ? new Date(r.followUp+'T12:00:00').toLocaleDateString('de-DE') : 'Kein Termin'}</span><h3>${escapeHtml(r.customer || 'Ohne Kundenname')}</h3><p>${escapeHtml(r.nextSteps || r.feedback || 'Noch keine nächste Aufgabe dokumentiert.')}</p><small>${escapeHtml(r.owner || 'Nicht zugewiesen')} · ${escapeHtml(r.result || 'Offen')}</small></div><div class="follow-actions"><select data-report-status="${r.index}" aria-label="Status"><option ${r.status==='Offen'?'selected':''}>Offen</option><option ${r.status==='In Bearbeitung'?'selected':''}>In Bearbeitung</option><option ${r.status==='Erledigt'?'selected':''}>Erledigt</option></select><button data-open-dashboard-report="${r.index}">Öffnen</button><button class="danger-link" data-delete-report="${r.index}">Löschen</button></div></article>`;
  const section = (title, items, tone, empty) => `<section class="follow-section"><div class="follow-section-head"><h2>${title}</h2><span>${items.length}</span></div>${items.length ? `<div class="follow-list">${items.map(r=>taskCard(r,tone)).join('')}</div>` : `<p class="follow-empty">${empty}</p>`}</section>`;
  return `<main class="page dashboard-page"><div class="section-heading"><div><span class="eyebrow">Interne Terminsteuerung</span><h1>Follow-up Dashboard</h1><p>Offene Aufgaben aus lokal gespeicherten Besuchsberichten. Alle Daten bleiben auf diesem Gerät.</p></div><button class="primary-button compact dashboard-new" data-action="new-report">Neuer Bericht</button></div>
    <section class="dashboard-stats"><div><span>Überfällig</span><strong>${overdue.length}</strong></div><div><span>Heute</span><strong>${dueToday.length}</strong></div><div><span>Geplant</span><strong>${upcoming.length}</strong></div><div><span>Erledigt</span><strong>${completed.length}</strong></div></section>
    ${section('Überfällige Follow-ups', overdue, 'overdue', 'Keine überfälligen Aufgaben.')}
    ${section('Heute fällig', dueToday, 'today', 'Heute ist kein Follow-up fällig.')}
    ${section('Kommende Termine', upcoming, 'upcoming', 'Keine kommenden Follow-ups geplant.')}
    ${section('Offen ohne Datum', openWithoutDate, 'undated', 'Alle offenen Aufgaben haben ein Datum.')}
    ${section('Erledigt', completed.slice(0,10), 'done', 'Noch keine Aufgabe als erledigt markiert.')}
  </main>`;
}

function updateSavedReportStatus(index, status) {
  if (!state.savedReports[index]) return;
  state.savedReports[index] = {...state.savedReports[index], status};
  localStorage.setItem('savedVisitReports', JSON.stringify(state.savedReports));
  render();
}

function deleteSavedReport(index) {
  if (!state.savedReports[index]) return;
  if (!confirm('Diesen gespeicherten Besuchsbericht wirklich löschen?')) return;
  state.savedReports.splice(index, 1);
  localStorage.setItem('savedVisitReports', JSON.stringify(state.savedReports));
  render();
}

