const PRODUCT_MANAGERS = [
  {area: 'Hände & Haut / Applikationshilfen', members: ['Nina Holzapfel', 'Luisa Stransky']},
  {area: 'Fläche – Wipes/Tücher', members: ['Marvin Sauber', 'Lukas Weisel', 'Nico Herwig']},
  {area: 'Dentalinstrumente', members: ['Franziska Schneider', 'Alexandra Koch']},
  {area: 'Fläche – Flüssig (GVS, Professional for You)', members: ['Selina Schäfer', 'Cornelia Kolle', 'Alicia Wagner']}
];
function pmEmail(name) {
  const norm = s => s.toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss');
  const parts = name.trim().split(/\s+/);
  const first = parts[0];
  const last = parts.slice(1).join('-');
  return `${norm(first)}.${norm(last)}@schumacher-online.com`;
}
function productManagementScreen() {
  return `<main class="page report-page">
    <div class="section-heading no-print"><div><span class="eyebrow">Intern</span><h1>Produktmanagement</h1><p>Zuständigkeiten der Produktmanager im Haus – für schnelle Rückfragen direkt per E-Mail.</p></div></div>
    <section class="pm-list">
      ${PRODUCT_MANAGERS.map(team => `<div class="pm-team"><h2>${escapeHtml(team.area)}</h2><div class="pm-members">${team.members.map(name => `<div class="pm-member"><span>${escapeHtml(name)}</span><a class="secondary-button" href="mailto:${pmEmail(name)}">${icon('talk')}<span>E-Mail</span></a></div>`).join('')}</div></div>`).join('')}
    </section>
  </main>`;
}
function messeScreen() {
  const chosen = favoriteEntries();
  const query = (state.messeQuery || '').toLowerCase();
  const pickable = query ? PRODUCTS.filter(p => `${p.name} ${p.kind}`.toLowerCase().includes(query)) : PRODUCTS;
  const canSend = state.messeName.trim() && (state.messeConsent || state.messeSignatureData);
  return `<main class="page report-page messe-page">
    <div class="section-heading no-print"><div><span class="eyebrow">Vor Ort erfassen</span><h1>Messe</h1><p>1. Produkte auswählen, die Sie besprochen haben – 2. Kundendaten eintragen – 3. direkt an den Innendienst senden. Alles bleibt zusätzlich lokal auf diesem Gerät.</p></div><button class="secondary-button" data-action="new-messe">Neue Erfassung</button></div>
    <h2 class="messe-step no-print">1. Besprochene Produkte auswählen</h2>
    ${coreCategoryGrid()}
    <section class="list-builder no-print">
      <div><h2>Besprochene Produkte (${chosen.length})</h2><div class="product-list">${chosen.map(e => summaryChosenCard(e)).join('') || '<div class="empty-state"><h2>Noch keine Produkte markiert</h2><p>Wählen Sie oben eine Kategorie und markieren Sie 1–2 Produkte mit dem Stern, oder wählen Sie rechts direkt aus.</p></div>'}</div></div>
      <div><h2>Weitere Produkte markieren</h2><label class="search-box summary-search">${icon('search')}<input id="messeSearch" value="${escapeHtml(state.messeQuery || '')}" placeholder="Produkt suchen"></label><div class="quick-product-list">${pickable.map(p => summaryProductCard(p)).join('') || '<p class="muted-copy">Kein Produkt gefunden.</p>'}</div></div>
    </section>
    <h2 class="messe-step no-print">2. Kundendaten erfassen</h2>
    <section class="report-form no-print">
      <label>Name / Firma<input data-messe-field="messeName" value="${escapeHtml(state.messeName)}" placeholder="z. B. Klinikum Musterstadt"></label>
      <label class="wide">Adresse<input data-messe-field="messeAdresse" value="${escapeHtml(state.messeAdresse)}" placeholder="Straße, PLZ, Ort"></label>
      <label>Ansprechpartner<input data-messe-field="messeAnsprechpartner" value="${escapeHtml(state.messeAnsprechpartner)}" placeholder="Name und Funktion"></label>
      <label>Einrichtungstyp<select data-messe-field="messeEinrichtungstyp">${['','Krankenhaus','Seniorenheim','Pflegeeinrichtung','Rettungsdienst','Sonstiges'].map(o=>`<option value="${o}" ${state.messeEinrichtungstyp===o?'selected':''}>${o||'Bitte wählen…'}</option>`).join('')}</select></label>
      <label>Datum<input data-messe-field="messeDatum" type="date" value="${escapeHtml(state.messeDatum)}"></label>
      <label>Ausgefüllt von<input data-messe-field="messeAusgefuelltVon" value="${escapeHtml(state.messeAusgefuelltVon)}" placeholder="Ihr Name"></label>
      <label class="wide">Gesprächsinhalt<textarea data-messe-field="messeGespraechsinhalt" placeholder="Worum ging es im Gespräch?">${escapeHtml(state.messeGespraechsinhalt)}</textarea></label>
      <label class="wide">Muster / Materialien für den Versand<textarea data-messe-field="messeMuster" placeholder="Welche Muster oder Unterlagen sollen zugesandt werden?">${escapeHtml(state.messeMuster)}</textarea></label>
    </section>
    <section class="messe-toggles no-print">
      <button class="filter-chip ${state.messeKontaktaufnahme ? 'active' : ''}" data-messe-toggle="messeKontaktaufnahme">Kontaktaufnahme gewünscht</button>
      <button class="filter-chip ${state.messeBemusterung ? 'active' : ''}" data-messe-toggle="messeBemusterung">Bemusterung gewünscht</button>
      <button class="filter-chip ${state.messeNewsletter ? 'active' : ''}" data-messe-toggle="messeNewsletter">Newsletter postalisch gewünscht</button>
    </section>
    <section class="messe-consent no-print">
      <h2>Einwilligung des Kunden</h2>
      <label class="consent-check"><input type="checkbox" id="messeConsent" ${state.messeConsent ? 'checked' : ''}><span>Der Kunde ist damit einverstanden, dass die oben angegebenen Daten zur Kontaktaufnahme und ggf. Zusendung von Informationsmaterial an Dr. Schumacher übermittelt werden.</span></label>
      <div class="signature-pad-wrap">
        <span>Unterschrift des Kunden (optional)</span>
        <canvas id="messeSignature" class="signature-pad" width="600" height="180"></canvas>
        <button class="secondary-button" data-action="clear-signature">Unterschrift löschen</button>
      </div>
    </section>
    <h2 class="messe-step no-print">3. Abschließen</h2>
    <div class="offer-actions wide no-print"><button class="primary-button compact" data-action="send-messe" ${canSend ? '' : 'disabled'}>${icon('talk')}<span>An Innendienst senden${state.region ? ` (Team ${regionLabel(state.region)})` : ''}</span></button></div>
    ${!innendienstEmail() ? '<small class="muted-copy no-print">Bitte zuerst in den Einstellungen Ihre Team-Region wählen, damit die E-Mail an das richtige Innendienst-Team geht.</small>' : ''}
  </main>`;
}
function initSignaturePad() {
  const canvas = document.getElementById('messeSignature');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  ctx.lineWidth = 2.2;
  ctx.lineCap = 'round';
  ctx.strokeStyle = '#173d65';
  if (state.messeSignatureData) {
    const img = new Image();
    img.onload = () => ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    img.src = state.messeSignatureData;
  }
  let drawing = false;
  const pos = (e) => {
    const rect = canvas.getBoundingClientRect();
    return { x: (e.clientX - rect.left) * (canvas.width / rect.width), y: (e.clientY - rect.top) * (canvas.height / rect.height) };
  };
  canvas.onpointerdown = (e) => { drawing = true; const p = pos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); e.preventDefault(); };
  canvas.onpointermove = (e) => { if (!drawing) return; const p = pos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); e.preventDefault(); };
  const stop = () => { if (!drawing) return; drawing = false; state.messeSignatureData = canvas.toDataURL('image/png'); };
  canvas.onpointerup = stop;
  canvas.onpointerleave = stop;
}
function buildMesseEmail() {
  const entries = favoriteEntries();
  const dateLabel = state.messeDatum ? new Date(state.messeDatum + 'T12:00:00').toLocaleDateString('de-DE') : new Date().toLocaleDateString('de-DE');
  const lines = [
    `Hallo Team,`, ``,
    `bei einer Messe wurde folgender Kontakt aufgenommen:`, ``,
    `Name / Firma: ${state.messeName || '-'}`,
    `Adresse: ${state.messeAdresse || '-'}`,
    `Ansprechpartner: ${state.messeAnsprechpartner || '-'}`,
    `Einrichtungstyp: ${state.messeEinrichtungstyp || '-'}`,
    `Datum: ${dateLabel}`,
    `Ausgefüllt von: ${state.messeAusgefuelltVon || '-'}`, ``,
    `Gesprächsinhalt:`,
    state.messeGespraechsinhalt || '-', ``
  ];
  lines.push('Besprochene Produkte:');
  if (entries.length) {
    entries.forEach(({product: p, size}) => lines.push(`- ${p.name}${size ? ' – ' + size : ''}`));
  } else {
    lines.push('-');
  }
  lines.push('');
  if (state.messeMuster.trim()) lines.push('Gewünschte Muster / Materialien:', state.messeMuster.trim(), '');
  lines.push(
    `Kontaktaufnahme gewünscht: ${state.messeKontaktaufnahme ? 'Ja' : 'Nein'}`,
    `Bemusterung gewünscht: ${state.messeBemusterung ? 'Ja' : 'Nein'}`,
    `Newsletter postalisch gewünscht: ${state.messeNewsletter ? 'Ja' : 'Nein'}`, ``,
    `Datenschutz-Einwilligung: ${(state.messeConsent || state.messeSignatureData) ? `Ja, digital bestätigt${state.messeSignatureData ? ' mit Unterschrift' : ''} am ${dateLabel}` : 'Nein'}`, ``,
    `Viele Grüße`
  );
  return { subject: `Neuer Messekontakt – ${state.messeName || 'ohne Namen'} – Dr. Schumacher`, body: lines.join('\n') };
}
function sendMesseEmail() {
  if (!state.messeName.trim() || !(state.messeConsent || state.messeSignatureData)) return;
  const { subject, body } = buildMesseEmail();
  openMailto(subject, body, innendienstEmail());
}
function resetMesseForm() {
  ['messeName','messeAdresse','messeAnsprechpartner','messeEinrichtungstyp','messeGespraechsinhalt','messeMuster'].forEach(key => { state[key] = ''; localStorage.removeItem(key); });
  state.messeDatum = new Date().toISOString().slice(0,10);
  localStorage.setItem('messeDatum', state.messeDatum);
  ['messeKontaktaufnahme','messeBemusterung','messeNewsletter'].forEach(key => { state[key] = false; localStorage.removeItem(key); });
  state.messeConsent = false;
  state.messeSignatureData = '';
  state.messeQuery = '';
  render();
}

function buildCrmSummary(report = state.visitReport) {
  const date = report.date ? new Date(report.date+'T12:00:00').toLocaleDateString('de-DE') : new Date().toLocaleDateString('de-DE');
  const parts = [
    `Besuchsbericht vom ${date}`,
    `Kunde/Einrichtung: ${report.customer || '-'}`,
    `Ansprechpartner: ${report.contacts || '-'}`,
    `Terminart: ${report.type || 'Produktvorstellung'}`,
    `Ausgangssituation / aktuelle Produkte: ${report.current || '-'}`,
    `Besprochene Produkte: ${report.products || '-'}`,
    `Feedback und Bedarf: ${report.feedback || '-'}`,
    `Muster / Unterlagen: ${report.samples || 'Keine'}`,
    `Ergebnis: ${report.result || 'Offen'}`,
    `Nächste Schritte: ${report.nextSteps || '-'}`,
    `Follow-up: ${report.followUp ? new Date(report.followUp+'T12:00:00').toLocaleDateString('de-DE') : '-'}`,
    `Verantwortlich: ${report.owner || '-'}`
  ];
  return parts.join('\n');
}

function saveVisitReportField(field, value) {
  state.visitReport = {...state.visitReport, [field]: value};
  localStorage.setItem('visitReport', JSON.stringify(state.visitReport));
}

function saveVisitReport() {
  const snapshot = {...state.visitReport, savedAt: new Date().toISOString()};
  state.savedReports = [snapshot, ...state.savedReports].slice(0,25);
  localStorage.setItem('savedVisitReports', JSON.stringify(state.savedReports));
  alert('Besuchsbericht wurde lokal gespeichert.');
  render();
}

function exportVisitReportCsv() {
  const r=state.visitReport;
  const headers=['Datum','Kunde','Ansprechpartner','Terminart','Ausgangssituation','Besprochene Produkte','Feedback','Muster/Unterlagen','Ergebnis','Nächste Schritte','Follow-up','Verantwortlich'];
  const values=[r.date||'',r.customer||'',r.contacts||'',r.type||'',r.current||'',r.products||'',r.feedback||'',r.samples||'',r.result||'',r.nextSteps||'',r.followUp||'',r.owner||''];
  const csv='\ufeff'+[headers,values].map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}); const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download='besuchsbericht-'+(r.customer||'kunde').replace(/[^a-z0-9äöüß-]+/gi,'-').toLowerCase()+'.csv'; a.click(); URL.revokeObjectURL(a.href);
}

function saveQuoteItem(key, field, value) {
  const current = state.quoteItems[key] || {};
  if (field === 'quantity') value = Math.max(1, Math.round(Number(value) || 1));
  if (field === 'discount') value = Math.min(100, Math.max(0, Number(value) || 0));
  state.quoteItems[key] = {...current, [field]: value};
  localStorage.setItem('quoteItems', JSON.stringify(state.quoteItems));
}

function exportOfferCsv() {
  const lines = [['Kunde','Ansprechpartner','Preisliste','Artikelnummer','Produkt','Gebinde','Menge','Rabatt %','Einzelpreis','Gesamtpreis']];
  favoriteEntries().forEach(({product: p, size}) => {
    const key = quoteKey(p.id, size);
    const saved=state.quoteItems[key]||{};
    const qty=Math.max(1,Number(saved.quantity)||1);
    const discount=Math.min(100,Math.max(0,Number(saved.discount)||0));
    const raw=resolvePrice(p,size); const unit=raw===''||raw==null?'':Number(raw);
    const total=unit===''?'':unit*qty*(1-discount/100);
    lines.push([state.quoteCustomer,state.quoteContact,state.priceList,resolveArtNr(p,size),p.name,size,qty,discount,unit,total]);
  });
  const csv='\ufeff'+lines.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}); const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download='angebotsentwurf-'+(state.quoteCustomer||'kunde').replace(/[^a-z0-9äöüß-]+/gi,'-').toLowerCase()+'.csv'; a.click(); URL.revokeObjectURL(a.href);
}

function buildOfferEmail() {
  let subtotal = 0;
  const lines = [
    `Hallo Team,`,
    ``,
    `bitte nachstehende Informationen an den Kunden senden.`,
    `Im Kundengespräch mit ${state.quoteCustomer || '(Kunde bitte ergänzen)'}${state.quoteContact ? ' (' + state.quoteContact + ')' : ''} wurden folgende Produkte ausgewählt:`,
    ``,
    `Preisliste: ${state.priceList}`,
    ``
  ];
  favoriteEntries().forEach(({product: p, size}) => {
    const key = quoteKey(p.id, size);
    const saved = state.quoteItems[key] || {};
    const quantity = Math.max(1, Number(saved.quantity) || 1);
    const discount = Math.min(100, Math.max(0, Number(saved.discount) || 0));
    const rawPrice = resolvePrice(p, size);
    const unitPrice = rawPrice === '' || rawPrice == null ? null : Number(rawPrice);
    const lineTotal = unitPrice == null ? null : unitPrice * quantity * (1 - discount / 100);
    if (lineTotal != null) subtotal += lineTotal;
    lines.push(`- ${p.name} (Art.-Nr. ${resolveArtNr(p, size)}), Gebinde ${size}, Menge ${quantity}${discount ? `, Rabatt ${discount}%` : ''}: ${unitPrice != null ? money(unitPrice) + ' / Stück, Summe ' + money(lineTotal) : 'Preis nicht hinterlegt'}`);
  });
  const vat = subtotal * 0.19;
  const total = subtotal + vat;
  lines.push('', `Zwischensumme: ${money(subtotal)}`, `zzgl. 19% MwSt.: ${money(vat)}`, `Gesamtsumme: ${money(total)}`);
  if (state.quoteNote) lines.push('', `Notiz: ${state.quoteNote}`);
  lines.push('', 'Bitte um Erstellung/Versand des Angebots an den Kunden.', 'Danke und Grüße');
  return {
    subject: `Angebot für ${state.quoteCustomer || 'Kundentermin'} – bitte an Kunden senden`,
    body: lines.join('\n')
  };
}

function sendOfferEmail() {
  const { subject, body } = buildOfferEmail();
  openMailto(subject, body, innendienstEmail());
}

function copyOfferEmail(button) {
  const { subject, body } = buildOfferEmail();
  copyEmailText(subject, body, button);
}

