function toggleCompare(id) {
  if (state.compareIds.includes(id)) state.compareIds = state.compareIds.filter(x => x !== id);
  else if (state.compareIds.length < 3) state.compareIds = [...state.compareIds, id];
  else { alert('Es können maximal drei Produkte verglichen werden.'); return; }
  localStorage.setItem('compareIds', JSON.stringify(state.compareIds));
  render();
}

function persistFavorites() { localStorage.setItem('favorites', JSON.stringify(state.favorites)); }

function toggleFavorite(id, size) {
  const p = PRODUCTS.find(x => x.id === id);
  if (!p) return;
  const resolvedSize = (size && p.sizes.includes(size)) ? size : p.sizes[0];
  const idx = state.favorites.findIndex(f => f.id === id && f.size === resolvedSize);
  if (idx >= 0) state.favorites.splice(idx, 1);
  else state.favorites = [...state.favorites, {id, size: resolvedSize}];
  persistFavorites();
  render();
}

function toggleFavoriteAny(id) {
  const has = state.favorites.some(f => f.id === id);
  if (has) {
    state.favorites = state.favorites.filter(f => f.id !== id);
  } else {
    const p = PRODUCTS.find(x => x.id === id);
    if (!p) return;
    state.favorites = [...state.favorites, {id, size: p.sizes[0]}];
  }
  persistFavorites();
  render();
}

function changeFavoriteSize(id, oldSize, newSize) {
  state.favorites = state.favorites.filter(f => !(f.id === id && f.size === newSize));
  const entry = state.favorites.find(f => f.id === id && f.size === oldSize);
  if (entry) entry.size = newSize;
  persistFavorites();
  render();
}

function saveQuoteField(key, value) { state[key]=value; localStorage.setItem(key,value); }

const BACKUP_KEYS = [
  'prices','priceImportMeta','favorites','recentProducts','compareIds',
  'quoteCustomer','quoteContact','quoteNote','quoteValidUntil','quoteItems','visitReport','savedVisitReports',
  'summaryCustomer','summaryOccasion','summaryIncludePrices','customerHistory','region','activeProfile','priceList',
  'messeName','messeAdresse','messeAnsprechpartner','messeEinrichtungstyp','messeDatum','messeAusgefuelltVon','messeGespraechsinhalt','messeMuster',
  'messeKontaktaufnahme','messeBemusterung','messeNewsletter'
];

function exportDeviceBackup() {
  const localData = {};
  BACKUP_KEYS.forEach(key => {
    const value = localStorage.getItem(key);
    if (value !== null) localData[key] = value;
  });
  const sessionData = {
    customerMode: sessionStorage.getItem('customerMode') || 'false'
  };
  const payload = {
    format: 'dr-schumacher-sales-companion-backup',
    version: '2.2',
    exportedAt: new Date().toISOString(),
    localData,
    sessionData
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], {type:'application/json'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'schumacher-app-sicherung-' + new Date().toISOString().slice(0,10) + '.json';
  a.click();
  URL.revokeObjectURL(a.href);
}

async function importDeviceBackup(event) {
  const file = event.target.files?.[0];
  if (!file) return;
  try {
    const payload = JSON.parse(await file.text());
    if (payload.format !== 'dr-schumacher-sales-companion-backup' || !payload.localData) {
      throw new Error('Die Datei ist keine gültige Sicherung dieser App.');
    }
    const keyCount = Object.keys(payload.localData).filter(key => BACKUP_KEYS.includes(key)).length;
    if (!confirm(`Sicherung vom ${new Date(payload.exportedAt || Date.now()).toLocaleString('de-DE')} wiederherstellen? Dabei werden ${keyCount} lokale Datenbereiche ersetzt.`)) {
      event.target.value = '';
      return;
    }
    BACKUP_KEYS.forEach(key => localStorage.removeItem(key));
    Object.entries(payload.localData).forEach(([key, value]) => {
      if (BACKUP_KEYS.includes(key) && typeof value === 'string') localStorage.setItem(key, value);
    });
    if (payload.sessionData) {
      ['customerMode'].forEach(key => {
        if (typeof payload.sessionData[key] === 'string') sessionStorage.setItem(key, payload.sessionData[key]);
      });
    }
    alert('Sicherung wurde erfolgreich wiederhergestellt. Die App wird neu geladen.');
    location.reload();
  } catch (error) {
    alert('Wiederherstellung fehlgeschlagen: ' + error.message);
    event.target.value = '';
  }
}

function snapshotCustomerData() {
  const entries = favoriteEntries().map(e => ({name: e.product.name, size: e.size}));
  const customer = state.summaryCustomer.trim() || state.quoteCustomer.trim();
  if (!entries.length && !customer) return;
  const snapshot = {
    date: new Date().toISOString(),
    customer: customer || '',
    occasion: state.summaryOccasion.trim(),
    products: entries
  };
  state.customerHistory = [snapshot, ...state.customerHistory].slice(0,5);
  localStorage.setItem('customerHistory', JSON.stringify(state.customerHistory));
}

function clearFavoritesOnly() {
  if (!state.favorites.length) return;
  if (!confirm('Alle markierten Favoriten löschen?')) return;
  snapshotCustomerData();
  state.favorites = [];
  localStorage.removeItem('favorites');
  render();
}

function customerHistoryScreen() {
  const items = state.customerHistory;
  return `<main class="page products-page"><div class="section-heading"><div><span class="eyebrow">Rückblick</span><h1>Letzte Kundengespräche</h1><p>Wird automatisch gesichert, sobald Sie „Speicher löschen – neuer Kunde" oder „Favoriten leeren" nutzen.</p></div></div>
  ${items.length ? items.map(snap => `<section class="advisor-results" style="margin-bottom:14px"><div class="section-heading"><div><span class="eyebrow">${escapeHtml(new Date(snap.date).toLocaleString('de-DE'))}</span><h2>${escapeHtml(snap.customer || 'Ohne Namen')}</h2></div></div>${snap.occasion ? `<p>${escapeHtml(snap.occasion)}</p>` : ''}${snap.products.length ? `<ul>${snap.products.map(p=>`<li>${escapeHtml(p.name)} – ${escapeHtml(p.size)}</li>`).join('')}</ul>` : '<p class="muted-copy">Keine Produkte markiert.</p>'}</section>`).join('') : '<div class="empty-state"><h2>Noch keine Einträge</h2><p>Sobald Sie den Speicher für einen neuen Kunden löschen, wird der vorherige Stand hier gesichert.</p></div>'}
  </main>`;
}

function resetCustomerData() {
  if (!confirm('Daten des aktuellen Kundengesprächs löschen? Sterne, Kundenzusammenfassung, Angebotsentwurf, Besuchsbericht-Entwurf und Messe-Erfassung werden zurückgesetzt. Preise und bereits gespeicherte Besuchsberichte bleiben erhalten.')) return;
  snapshotCustomerData();
  ['favorites','summaryCustomer','summaryOccasion','summaryIncludePrices','quoteCustomer','quoteContact','quoteNote','quoteValidUntil','quoteItems','visitReport','messeName','messeAdresse','messeAnsprechpartner','messeEinrichtungstyp','messeGespraechsinhalt','messeMuster','messeKontaktaufnahme','messeBemusterung','messeNewsletter'].forEach(key => localStorage.removeItem(key));
  state.favorites = [];
  state.summaryCustomer = '';
  state.summaryOccasion = 'unser heutiges Gespräch';
  state.summaryIncludePrices = false;
  state.quoteCustomer = '';
  state.quoteContact = '';
  state.quoteNote = '';
  state.quoteValidUntil = '';
  state.quoteItems = {};
  state.visitReport = {};
  state.messeName = '';
  state.messeAdresse = '';
  state.messeAnsprechpartner = '';
  state.messeEinrichtungstyp = '';
  state.messeGespraechsinhalt = '';
  state.messeMuster = '';
  state.messeKontaktaufnahme = false;
  state.messeBemusterung = false;
  state.messeNewsletter = false;
  state.messeConsent = false;
  state.messeSignatureData = '';
  state.messeDatum = new Date().toISOString().slice(0,10);
  localStorage.setItem('messeDatum', state.messeDatum);
  alert('Kundendaten wurden zurückgesetzt. Bereit für den nächsten Termin.');
  state.screen = 'menu';
  render();
}

function exportPrices() { if (!can('prices')) { alert('Für diese Rolle ist der Export nicht freigeschaltet.'); return; } const payload={exportedAt:new Date().toISOString(),meta:state.importMeta,prices:state.prices}; const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='schumacher-preisstand-'+new Date().toISOString().slice(0,10)+'.json'; a.click(); URL.revokeObjectURL(a.href); }

async function importExcel(event) {
  if (!can('prices')) { alert('Für diese Rolle ist der Preisimport nicht freigeschaltet.'); return; }
  const status = $('#importStatus');
  const file = event.target.files[0];
  if (!file) return;
  if (typeof XLSX === 'undefined') { status.textContent='Excel-Modul konnte nicht geladen werden. Bitte Internetverbindung prüfen.'; return; }
  try {
    status.textContent = 'Preisliste wird geprüft …';
    const isCsv = /\.csv$/i.test(file.name);
    const workbook = isCsv ? XLSX.read(await file.text(), {type:'string'}) : XLSX.read(await file.arrayBuffer());
    const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], {defval:''});
    const mapped = {};
    const errors = [];
    let duplicates = 0;
    let validRows = 0;
    for (let index = 0; index < rows.length; index++) {
      const row = rows[index];
      const line = index + 2;
      const sku = String(row.Artikelnummer || row.SKU || row['Artikel-Nr.'] || '').trim();
      const size = String(row.Gebinde || row.Gebindegröße || '').trim();
      if (!sku) { errors.push(`Zeile ${line}: Artikelnummer fehlt`); continue; }
      const values = {UVP:toNumber(row.UVP), 'PL 1':toNumber(row.PL1 ?? row['PL 1']), 'PL 2':toNumber(row.PL2 ?? row['PL 2']), 'PL 3':toNumber(row.PL3 ?? row['PL 3']), 'PL 4':toNumber(row.PL4 ?? row['PL 4']), 'PL 5':toNumber(row.PL5 ?? row['PL 5'])};
      if (Object.values(values).every(v => v === '')) { errors.push(`Zeile ${line}: keine Preise vorhanden`); continue; }
      if (!mapped[sku]) mapped[sku] = {sizes:{}};
      if (size) {
        if (mapped[sku].sizes[size]) duplicates++;
        mapped[sku].sizes[size] = values;
      } else {
        if (Object.keys(mapped[sku]).some(k => k !== 'sizes')) duplicates++;
        Object.assign(mapped[sku], values);
      }
      validRows++;
    }
    state.prices = mapped;
    localStorage.setItem('prices', JSON.stringify(mapped));
    state.importMeta={file:file.name,date:new Date().toLocaleString('de-DE'),rows:validRows};
    localStorage.setItem('priceImportMeta',JSON.stringify(state.importMeta));
    const matchedProducts = PRODUCTS.filter(p => mapped[p.sku]).length;
    const unknownSkus = Object.keys(mapped).filter(sku => !PRODUCTS.some(p => p.sku === sku));
    const summary = `${validRows} gültige Preiszeilen · ${matchedProducts} Produkte zugeordnet` +
      (unknownSkus.length ? ` · ${unknownSkus.length} unbekannte Artikelnummern` : '') +
      (duplicates ? ` · ${duplicates} Dubletten überschrieben` : '') +
      (errors.length ? ` · ${errors.length} Fehler` : '');
    status.innerHTML = `<strong>${summary}</strong>${errors.length ? `<details><summary>Fehler anzeigen</summary><div>${errors.slice(0,20).map(escapeHtml).join('<br>')}</div></details>` : ''}`;
  } catch (error) { status.textContent='Import fehlgeschlagen: '+error.message; }
}
function toNumber(value) {
  if (value==='' || value==null) return '';
  if (typeof value==='number') return value;
  return Number(String(value).replace(/\./g,'').replace(',','.').replace(/[^0-9.-]/g,''));
}
function normSheetKey(s) {
  return String(s||'').toUpperCase().replace(/®/g,'').replace(/[^A-Z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
}
function normalizeSheetSize(raw) {
  const s = String(raw||'').trim();
  if (!s) return '';
  const m = s.match(/^(\d+(?:,\d+)?)\s*(ml|L|g|kg)$/i);
  if (!m) return s;
  const unit = m[2].toLowerCase()==='l' ? 'L' : m[2].toLowerCase();
  return `${m[1]} ${unit}`;
}
function extractVE(row) {
  // Normally the sheet's VE column is a bare shipping-unit count. For a few rows
  // (Inhalt/VE/Gebinde shifted, e.g. some Wipes SKUs) that count ends up under
  // Gebinde instead — fall back there if VE itself isn't a plain number.
  const veRaw = String(row['VE']||'').trim();
  if (/^\d+([.,]\d+)?$/.test(veRaw)) return veRaw;
  const gebindeRaw = String(row['Gebinde']||'').trim();
  if (/^\d+([.,]\d+)?$/.test(gebindeRaw)) return gebindeRaw;
  return '';
}
function resolveSizeLabel(product, baseSize, gebinde) {
  const candidates = product.sizes.filter(s => s === baseSize || s.startsWith(baseSize + ' ('));
  if (candidates.length <= 1) return candidates[0] || baseSize;
  const gebindeWords = new Set(String(gebinde||'').toLowerCase().match(/[a-zäöü]+/g) || []);
  let best = candidates[0], bestScore = -1;
  candidates.forEach(c => {
    const cWords = new Set(c.toLowerCase().match(/[a-zäöü]+/g) || []);
    const score = [...gebindeWords].filter(w => cWords.has(w)).length;
    if (score > bestScore) { bestScore = score; best = c; }
  });
  return best;
}
async function syncLivePrices(manual=false) {
  const status = $('#importStatus');
  if (manual && status) status.textContent = 'Preise werden von Google Sheets geladen …';
  try {
    if (typeof XLSX === 'undefined') throw new Error('Excel-Modul nicht geladen');
    const res = await fetch(PRICE_SHEET_CSV_URL, {cache:'no-store'});
    if (!res.ok) throw new Error('HTTP '+res.status);
    const text = await res.text();
    const workbook = XLSX.read(text, {type:'string'});
    const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], {defval:''});
    const groups = {};
    rows.forEach(row => {
      const key = normSheetKey((row['Produkt']||'') + ' ' + (row['Variante']||''));
      if (!key) return;
      (groups[key] = groups[key] || []).push(row);
    });
    const groupKeys = Object.keys(groups);
    const mapped = {};
    const sizeArtNr = {};
    const sizeVE = {};
    let matchedProducts = 0;
    PRODUCTS.forEach(p => {
      const pk = normSheetKey(p.name);
      let key = groups[pk] ? pk : null;
      if (!key) {
        let best = null, bestLen = -1;
        groupKeys.forEach(k => {
          if (k===pk) return;
          if ((k.includes(pk) || pk.includes(k)) && k.length>bestLen) { best=k; bestLen=k.length; }
        });
        key = best;
      }
      if (!key) return;
      const sizes = {};
      const artNr = {};
      const ve = {};
      groups[key].forEach(row => {
        const hasPrice = ['Preisliste UVP','Preisliste 1','Preisliste 2','Preisliste 3','Preisliste 4','Preisliste 5'].some(c => toNumber(row[c]) !== '');
        let baseSize = normalizeSheetSize(row['Inhalt']) || (hasPrice ? p.sizes[0] : '');
        if (!baseSize) return;
        let size = resolveSizeLabel(p, baseSize, row['Gebinde']);
        if (!p.sizes.includes(size)) {
          // Inhalt didn't match any known size (e.g. sheet columns shifted for this row) — try VE as a fallback source
          const altBase = normalizeSheetSize(row['VE']);
          if (altBase) {
            let altSize = resolveSizeLabel(p, altBase, row['Gebinde']);
            if (!p.sizes.includes(altSize) && /^\d+$/.test(altBase)) {
              // VE is a bare count (e.g. "6") for accessory/Stück products — retry as "6 Stück"
              altSize = resolveSizeLabel(p, altBase + ' Stück', row['Gebinde']);
            }
            if (p.sizes.includes(altSize)) size = altSize;
          }
        }
        if (!p.sizes.includes(size)) return;
        const rowArtNr = String(row['Art. Nr.']||'').trim();
        // Several sheet rows can collide onto the same resolved size (e.g. regional
        // packaging variants). Keep the first match, but let the row matching the
        // product's own catalog SKU win regardless of row order, since that's the
        // one already verified correct in the product data.
        const preferRow = !sizes[size] || rowArtNr === p.sku;
        if (preferRow) {
          sizes[size] = {
            UVP: toNumber(row['Preisliste UVP']),
            'PL 1': toNumber(row['Preisliste 1']),
            'PL 2': toNumber(row['Preisliste 2']),
            'PL 3': toNumber(row['Preisliste 3']),
            'PL 4': toNumber(row['Preisliste 4']),
            'PL 5': toNumber(row['Preisliste 5'])
          };
        }
        if (rowArtNr && (!artNr[size] || rowArtNr === p.sku)) artNr[size] = rowArtNr;
        const rowVE = extractVE(row);
        if (rowVE && (!ve[size] || rowArtNr === p.sku)) ve[size] = rowVE;
      });
      // A handful of SKUs are genuinely cross-listed under two different catalog
      // entries (same physical article, different product name/category) — merge
      // per-size rather than overwrite so neither product's data clobbers the other's.
      if (Object.keys(sizes).length) { mapped[p.sku] = { sizes: { ...((mapped[p.sku] && mapped[p.sku].sizes) || {}), ...sizes } }; matchedProducts++; }
      if (Object.keys(artNr).length) sizeArtNr[p.sku] = { ...(sizeArtNr[p.sku] || {}), ...artNr };
      if (Object.keys(ve).length) sizeVE[p.sku] = { ...(sizeVE[p.sku] || {}), ...ve };
    });
    if (!matchedProducts) throw new Error('Keine Preise im Sheet gefunden');
    state.prices = mapped;
    state.sizeArtNr = sizeArtNr;
    state.sizeVE = sizeVE;
    localStorage.setItem('prices', JSON.stringify(mapped));
    localStorage.setItem('sizeArtNr', JSON.stringify(sizeArtNr));
    localStorage.setItem('sizeVE', JSON.stringify(sizeVE));
    state.importMeta = {file:'Google Sheets (live)', date:new Date().toLocaleString('de-DE'), ts:Date.now(), rows: matchedProducts, source:'sheet'};
    localStorage.setItem('priceImportMeta', JSON.stringify(state.importMeta));
    if (state.screen==='settings' || state.screen==='detail' || state.screen==='products') render();
  } catch (error) {
    if (manual && status) status.textContent = 'Live-Abgleich fehlgeschlagen: ' + error.message + ' – zuletzt gespeicherter Preisstand bleibt aktiv.';
    console.warn('Preis-Sync von Google Sheets fehlgeschlagen', error);
  }
}

render();
if ('serviceWorker' in navigator) navigator.serviceWorker.register('service-worker.js').catch(() => {});
syncLivePrices();
setInterval(() => { if (document.visibilityState === 'visible') syncLivePrices(); }, 20 * 60 * 1000);
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') {
    const last = (state.importMeta && state.importMeta.ts) || 0;
    if (Date.now() - last > 15 * 60 * 1000) syncLivePrices();
  }
});
